public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        List<Integer> list = new ArrayList<>();
        list.add(nums[0]);
        result.add(list);
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<Integer> subList = new ArrayList<>();
        subList.add(num);
        for (int j = 0; j < nums.length; j++) {
            if (j != i) {
                subList.add(nums[j]);
            }
        }
        List<List<Integer>> subResult = permute(subList.toArray());
        for (List<Integer> subPermutation : subResult) {
            subPermutation.add(0, num);
            result.add(subPermutation);
        }
    }
    return result;
}

public int findLargestSubstring(List<String> strings) {
    // Initialize the largest substring length to 0
    int largestSubstringLength = 0;

    // Iterate over each string in the list
    for (String string : strings) {
        // Get the length of the string
        int stringLength = string.length();

        // Check if the string is longer than the current largest substring
        if (stringLength > largestSubstringLength) {
            // If the string is longer, set it as the new largest substring
            largestSubstringLength = stringLength;
        }

        // Check if the inverse of the string is longer than the current largest substring
        if (stringLength > largestSubstringLength) {
            // If the inverse of the string is longer, set it as the new largest substring
            largestSubstringLength = stringLength;
        }
    }

    // Return the largest substring length
    return largestSubstringLength;
}

