public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersections are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Check if the paths are valid
    for (int[] path : paths) {
        if (path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n) {
            return "cannot be travelled";
        }
    }

    // Check if the starting and ending n-tersections are connected by a path
    boolean foundStart = false;
    boolean foundEnd = false;
    for (int[] path : paths) {
        if (path[0] == start[0] && path[1] == start[1]) {
            foundStart = true;
        }
        if (path[0] == end[0] && path[1] == end[1]) {
            foundEnd = true;
        }
    }
    if (!foundStart || !foundEnd) {
        return "cannot be travelled";
    }

    // Check if the paths form a valid path from the starting to the ending n-tersection
    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    visited[start[0]][start[1]] = true;
    while (!queue.isEmpty()) {
        int[] current = queue.remove();
        for (int[] path : paths) {
            if (path[0] == current[0] && path[1] == current[1]) {
                if (path[0] == end[0] && path[1] == end[1]) {
                    return "can be travelled";
                }
                if (!visited[path[0]][path[1]]) {
                    queue.add(path);
                    visited[path[0]][path[1]] = true;
                }
            }
        }
    }

    // If the starting and ending n-tersections are not connected by a path, return "cannot be travelled"
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int word1Length = word1.length();
    int word2Length = word2.length();
    int gcd = gcd(word1Length, word2Length);
    int numerator = commonLetters * word1Length * word2Length;
    int denominator = gcd * gcd;
    return numerator + "/" + denominator;
}

private static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

