public int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> numMap = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (numMap.containsKey(complement)) {
            return new int[]{numMap.get(complement), i};
        }
        numMap.put(nums[i], i);
    }
    return new int[]{-1, -1};
}

public int search(int[] nums, int target) {
    int start = 0;
    int end = nums.length - 1;

    while (start < end) {
        int mid = start + (end - start) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[start] <= nums[mid]) {
            if (nums[start] <= target && target < nums[mid]) {
                end = mid - 1;
            } else {
                start = mid + 1;
            }
        } else {
            if (nums[mid] < target && target <= nums[end]) {
                start = mid + 1;
            } else {
                end = mid - 1;
            }
        }
    }

    if (nums[start] == target) {
        return start;
    }

    return -1;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the number of elements to remove from the smallest and largest 5%
    int numElementsToRemove = (int) (arr.length * 0.05);

    // Remove the smallest and largest 5% of elements
    int[] trimmedArr = Arrays.copyOfRange(arr, numElementsToRemove, arr.length - numElementsToRemove);

    // Calculate the mean of the remaining elements
    double mean = trimmedArr.stream().mapToDouble(i -> i).average().getAsDouble();

    // Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000;
}

