public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Initialize a set to store the visited nodes
    Set<Integer> visited = new HashSet<>();

    // Initialize a variable to store the minimum time
    int minTime = 0;

    // Start at node 0
    queue.offer(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node
        int current = queue.poll();

        // If the current node has an apple, add its time to the minimum time
        if (hasApple[current]) {
            minTime++;
        }

        // Mark the current node as visited
        visited.add(current);

        // Loop through the neighbors of the current node
        for (int neighbor : graph.neighbors(current)) {
            // If the neighbor has not been visited, add it to the queue
            if (!visited.contains(neighbor)) {
                queue.offer(neighbor);
            }
        }
    }

    // Return the minimum time
    return minTime;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (!s.isEmpty()) {
        // Pick the smallest character from s and append it to the result
        char smallest = s.charAt(0);
        result.append(smallest);
        s = s.substring(1);

        // Pick the smallest character from s which is greater than the last appended character to the result and append it
        int smallestIndex = s.indexOf(smallest);
        while (smallestIndex != -1) {
            smallestIndex = s.indexOf(smallest, smallestIndex + 1);
            if (smallestIndex != -1) {
                result.append(s.charAt(smallestIndex));
                s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);
            }
        }

        // Pick the largest character from s and append it to the result
        char largest = s.charAt(s.length() - 1);
        result.append(largest);
        s = s.substring(0, s.length() - 1);

        // Pick the largest character from s which is smaller than the last appended character to the result and append it
        int largestIndex = s.lastIndexOf(largest);
        while (largestIndex != -1) {
            largestIndex = s.lastIndexOf(largest, largestIndex - 1);
            if (largestIndex != -1) {
                result.append(s.charAt(largestIndex));
                s = s.substring(0, largestIndex) + s.substring(largestIndex + 1);
            }
        }
    }
    return result.toString();
}

