public int findMinFibonacciNumbers(int k) {
    if (k <= 1) {
        return k;
    }

    int[] fib = new int[k];
    fib[0] = 1;
    fib[1] = 1;

    for (int i = 2; i < k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    int min = Integer.MAX_VALUE;
    for (int i = 0; i < k; i++) {
        if (fib[i] == k) {
            return 1;
        } else if (fib[i] > k) {
            break;
        } else {
            min = Math.min(min, fib[i]);
        }
    }

    return min;
}

public int kthFactor(int n, int k) {
    // Find all factors of n
    ArrayList<Integer> factors = new ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }

    // Sort the factors in ascending order
    Collections.sort(factors);

    // Return the kth factor or -1 if there are fewer than k factors
    if (factors.size() < k) {
        return -1;
    } else {
        return factors.get(k - 1);
    }
}

