    int n = mat[0].length;
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int length = 1;
                for (int k = i + 1; k < m && mat[k][j] == 1; k++) {
                    length++;
                }
                for (int k = j + 1; k < n && mat[i][k] == 1; k++) {
                    length++;
                }
                maxLength = Math.max(maxLength, length);
            }
        }
    }

    return maxLength;
}

public static String addThousandSeparator(int n) {
