    int slope2 = (points[2][1] - points[1][1]) / (points[2][0] - points[1][0]);

    // Check if the slopes are equal
    if (slope1 == slope2) {
        return false;
    }

    // Calculate the slope of the third line
    int slope3 = (points[2][1] - points[0][1]) / (points[2][0] - points[0][0]);

